Translate("deDE", "swamp-of-sorrows", {
	title = "Sümpfe des Elends",
	aliases = { "die Sümpfe des Elends" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Sümpfe des Elends sind ein versunkenes Land aus schwarzem Wasser, hängendem Moos und endlosem Regen im Südosten der {link:eastern-kingdoms}Östlichen Königreiche{/link}. Sie liegen östlich des {link:deadwind-pass}Gebirgspasses der Totenwinde{/link} und nördlich der {link:blasted-lands}Verwüsteten Lande{/link}, und ihre Ostküste bricht sich am verbotenen Meer. Ihre Bäume stehen bis zum Knie im Wasser, ihre Pfade verschwinden unter dem Schlamm, und in ihren Tümpeln brüten Krokilisken, große Spinnen und wandelnde Knäuel aus lebendigem Kraut. Kein Königreich hat sie je gezähmt. Die {link:orcs}Orcs{/link} der {link:horde}Horde{/link} halten eine Festung in ihrem Herzen, eine kleine Schar von Verbannten klammert sich an ihren Westrand, {link:murlocs}Murlocs{/link} schwärmen entlang ihrer Küste, und grüne Drachen halten stumme Wache über einem See, in dem ein Trolltempel versunken liegt.]=],
		},
		{
			title = "Ursprünge",
			text = [=[Keine Chronik verzeichnet, wer dem Sumpf zuerst seinen Namen gab oder warum er ein Ort des Elends genannt wurde. In Erinnerung ist, dass er seit Langem ein Land der Verbannten ist. Als die Gurubashitrolle ihren Blutgott {link:hakkar}Hakkar{/link} stürzten, vertrieben sie seine Priester, die Atal'ai, aus den Dschungeln des Südens. Die Atal'ai flohen nach Norden in diese {link:the-marshlands}Marschen{/link}. Dort errichteten sie einen großen Tempel, den {link:temple-of-atal-hakkar}Tempel von Atal'Hakkar{/link}, in dem sie ihren Gott in die Welt zurückrufen wollten. Der grüne Drachenschwarm von {red:ysera}Ysera{/red} ließ es nicht zu. Die Drachen zerschlugen den Tempel und versenkten ihn unter den Wassern des Tränenteichs, und dort liegt er noch immer. Keine Chronik nennt das Jahr.

Südlich des Sumpfes lag das schwarze Fenn. Dort öffnete sich das {link:dark-portal}Dunkle Portal{/link}, und von dort zog die {link:horde}Horde{/link} der {link:orcs}Orcs{/link} aus, um im {link:first-war}Ersten Krieg{/link} gegen das Königreich {link:azeroth}Azeroth{/link} Krieg zu führen. Der Sumpf war der erste Nachbar der Horde in dieser Welt.]=],
		},
		{
			title = "Die Gegenwart",
			text = [=[Der Sumpf ist umkämpftes Land. Der Kriegshäuptling {link:thrall}Thrall{/link} unterhält die Festung {link:stonard}Stonard{/link} in seiner Mitte, und seine {link:orcs}Orcs{/link} haben Gesandte geschickt, um zu erfahren, was dem versunkenen Tempel widerfuhr. Die {link:alliance}Allianz{/link} hält hier keine Stadt. Ihre Karawanen ziehen nur auf der langen Straße vom {link:duskwood}Dämmerwald{/link} zur {link:nethergarde-keep}Burg Nethergarde{/link} hindurch, und viele von ihnen kommen nie an. Im Norden macht ein Volk, das man die Verirrten nennt, Jagd auf jeden, der sich ihrem Dorf nähert. Im Westen verbirgt sich im sicheren Hafen eine Schar verbannter Draenei, die ihr Blut teilen, aber nicht ihren Wahnsinn. Entlang der Ostküste werden die {link:murlocs}Murlocs{/link} mit jeder Jahreszeit dreister. Und über allem kreisen die grünen Drachen und warten, und sie bewachen den Tempel gegen den Tag, an dem sich seine Priester wieder regen.]=],
		},
		{
			title = "Bewohner",
			text = [=[• {b}Die {link:orcs}Orcs{/link} von {link:stonard}Stonard{/link}.{/b} Krieger, Späher und Händler der {link:horde}Horde{/link}, die die einzige Festung des Sumpfes halten und seine Straßen und seine Küste bewachen.
• {b}Die Draenei des sicheren Hafens.{/b} Eine kleine Schar Verbannter im Westen, die von weit her nach {link:azeroth}Azeroth{/link} kamen und nun ihre eigenen Verwandten fürchten.
• {b}Die Verirrten.{/b} Verwandte der Draenei, in den Wahnsinn getrieben von der langen Reise, die sie hierherbrachte. Sie halten das {link:fallow-sanctuary}Fallow Heiligtum{/link} im Norden.
• {b}Der grüne Drachenschwarm.{/b} Welpen, Wyrmkin und Schuppenbanne aus Yseras Schwarm bewachen den {link:pool-of-tears}Tränenteich{/link} und die Lande ringsum. Ein Drache namens {link:itharius}Itharius{/link} bewohnt eine Höhle im Südwesten.
• {b}Murlocs.{/b} Die {link:murlocs}Murlocstämme{/link} des Nebelschilfstrands schwärmen entlang der Ostküste.
• {b}Die Tiere der Marsch.{/b} Sägezahnkrokilisken, Jaguare, Panther, große Spinnen und die wandelnden Kräuter, die man Sumpfwandler und verschlungene Schrecken nennt.
• {b}Die Atal'ai.{/b} Die Trollpriester Hakkars hausen noch immer im versunkenen Tempel unter dem Tränenteich.]=],
		},
		{
			title = "Geschichte",
			text = [=[• {b}Die Verbannung der Atal'ai.{/b} Von den Gurubashi verstoßen, errichteten die Priester Hakkars ihren Tempel im Sumpf.
• {b}Der Untergang des Tempels.{/b} Der grüne Drachenschwarm zerschmetterte den Tempel und versenkte ihn, damit {link:hakkar}der Blutgott{/link} nicht durch ihn zurückkehren konnte.
• {b}Der Erste Krieg.{/b} Das Dunkle Portal öffnete sich im schwarzen Fenn im Süden, und am Rand des Sumpfes setzte die {link:horde}Horde{/link} zum ersten Mal ihren Fuß in diese Welt.
• {b}Die Gründung Stonards.{/b} Keine Chronik verzeichnet, wann die {link:orcs}Orcs{/link} {link:stonard}Stonard{/link} errichteten. Heute ist es die Festung des Kriegshäuptlings im Süden, versorgt über eine lange Nachschubstraße vom Lager {link:grom-gol-base-camp}Grom'gol{/link} im {link:stranglethorn-vale}Schlingendorntal{/link}.
• {b}Die Gegenwart.{/b} Die Horde erforscht den Tempel, die {link:alliance}Allianz{/link} treibt ihre Karawanen eilig vorbei, und die Drachen warten.]=],
		},
		{
			title = "Überlieferungen des Sumpfes",
			text = [=[• Die {link:explorers-league}Forscherliga{/link} von {link:ironforge}Ironforge{/link} sucht seit Langem den {link:temple-of-atal-hakkar}Tempel von Atal'Hakkar{/link}. Ein alter {link:dwarves}Zwerg{/link} der Liga überflog den Sumpf auf einem Greifen und fand ihn nie. Gefunden wurde er erst vom Boden aus, versunken unter dem {link:pool-of-tears}Tränenteich{/link}.
• Die Draenei nennen einen heiligen Kristall Draenethyst. Er soll von einem Ort stammen, an dem Berge fliegen und Dämonen herrschen. Ein Schamane der {link:centaurs}Zentauren{/link} in {link:desolace}Desolace{/link} ließ einst einen Splitter davon aus dem Sumpf holen.
• Ein Kurier der {link:kirin-tor}Kirin Tor{/link} verlor hier einst eine kostbare Abhandlung. Sie war von {link:khadgar}Khadgar{/link} verfasst und für {link:nethergarde-keep}Burg Nethergarde{/link} bestimmt, und die wandelnden Kräuter der Marsch nahmen sie ihm ab.
• Unter einer alten Brücke im Westen des Sumpfes, nahe der Straße vom {link:deadwind-pass}Gebirgspass der Totenwinde{/link}, werden hingekritzelte Rätsel für Schatzsucher hinterlassen. Die Rätsel sprechen von einem Mann namens Cortello, und sie führen über das Meer und wieder zurück.
• Goblins zahlen gut für Traumstaub, ein glitzerndes Pulver, das man von den Drachenwelpen des Sumpfes gewinnt.]=],
		},
	},
})

Translate("deDE", "stonard", {
	title = "Stonard",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Stonard ist die Festung der {link:horde}Horde{/link} im Herzen des Sumpfes. Ihre Mauern aus dunklem Stein und schwerem Gebälk erheben sich auf trockenem Grund zwischen den Tümpeln, und ihre Türme blicken meilenweit über Schilf und Wasser. Sie ist der stärkste Sitz des Kriegshäuptlings im Süden der {link:eastern-kingdoms}Östlichen Königreiche{/link}. Von hier tragen Depeschenreiter Befehle in die {link:blasted-lands}Verwüsteten Lande{/link}, Läufer bringen Berichte nach {link:kargath}Kargath{/link} im {link:badlands}Ödland{/link}, und Windreiter fliegen nach Norden. Lehrer jeder Berufung haben ihre Hallen innerhalb der Mauern, und ein Händler verschifft das Fleisch der Küste zurück nach {link:orgrimmar}Orgrimmar{/link}.]=],
		},
		{
			title = "Innerhalb der Mauern",
			text = [=[Stonard hat einen Gefangenen. Ein menschlicher Spion der {link:alliance}Allianz{/link} wird unter Bewachung gehalten, und er behauptet, von Verrat zu wissen, der über die Allianz selbst hinausreicht. Die Festung beherbergt auch den Gesandten des Kriegshäuptlings, {link:fel-zerul}Fel'zerul{/link}, der geschickt wurde, um das Schicksal des versunkenen Tempels zu ergründen.]=],
		},
	},
})

Translate("deDE", "pool-of-tears", {
	title = "Tränenteich",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Tränenteich ist ein weiter, stiller See im Osten des Sumpfes. Zerbrochene Säulen und die Stümpfe alter Treppen ragen aus seinen Untiefen. Unter seinen Wassern liegt der {link:temple-of-atal-hakkar}Tempel von Atal'Hakkar{/link}, den der grüne Drachenschwarm zerschlug und versenkte, damit die Priester {link:hakkar}Hakkar{/link}s ihre Beschwörung niemals vollenden konnten. Im Schlamm seiner Ufer findet man noch immer Bruchstücke der Atal'ai: Götzenbilder, Fetische und gemeißelte Steine. Die Drachen aus Yseras Schwarm bewachen den See. Wyrmkin und Schuppenbanne stehen an seinen Ufern, und sie dulden niemanden ohne Grund in ihrer Nähe. Die Atal'ai hausen noch immer in den versunkenen Hallen darunter.]=],
		},
	},
})

Translate("deDE", "fallow-sanctuary", {
	title = "Das Fallow Heiligtum",
	aliases = { "Fallow Heiligtum" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Das Fallow Heiligtum ist das Dorf der Verirrten im Norden des Sumpfes. Seine Hütten aus Schilf und Fell drängen sich um Kochfeuer, und seine Jäger, Fischer und Seher ziehen von dort hinaus in die Marsch. Die Verirrten sehen aus wie die Draenei des sicheren Hafens, denn einst waren sie ein Volk. Doch die lange Reise, die sie nach {link:azeroth}Azeroth{/link} brachte, zerbrach ihren Verstand, und nun ergreifen oder töten sie jeden, der sich in ihre Nähe verirrt. Zwischen ihren Hütten türmt sich Diebesgut: heilige Draenethystkristalle, die aus dem sicheren Hafen geraubt wurden, und die Wagen einer Karawane der {link:alliance}Allianz{/link}. Ihr Häuptling herrscht über das Dorf. Ein Verirrter namens {link:ongeku}Ongeku{/link} hütet dort einen Splitter Draenethyst als sein Eigentum.]=],
		},
	},
})

Translate("deDE", "the-harborage", {
	title = "Der sichere Hafen",
	aliases = { "sicherer Hafen" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der sichere Hafen ist eine kleine Zuflucht im Nordwesten des Sumpfes, wo eine Schar verbannter Draenei ihre Heimat gefunden hat. Sie sind wenige und schlecht bewaffnet. Ihre Verwandten, die Verirrten des Fallow Heiligtums, haben ihre heiligen Kristalle gestohlen, und ein Rohling namens {link:noboru-the-cudgel}Noboru{/link} macht seit Monaten mit seinem Knüppel Jagd auf sie. {link:magtoor}Magtoor{/link} spricht für die Verbannten, und ein Lederverarbeiter namens Masat T'andr arbeitet unter ihnen. Sie heißen Reisende jedes Banners willkommen, die in Frieden kommen, denn sie haben nicht die Kraft, jemanden abzuweisen.]=],
		},
	},
})

Translate("deDE", "itharius-s-cave", {
	title = "Itharius' Höhle",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Itharius' Höhle liegt im äußersten Südwesten des Sumpfes, verborgen zwischen tropfenden Bäumen nahe der Grenze zu den {link:blasted-lands}Verwüsteten Landen{/link}. Sie ist der Hort von {link:itharius}Itharius{/link}, einem Drachen des grünen Schwarms. Junge Welpen seiner Art schlafen und spielen in der Marsch vor ihrem Eingang, und der Staub, der von ihren Flügeln fällt, schimmert im Dämmerlicht wie Reif. Wenige kommen ungebeten hierher. Wer kommt, sucht meist Hilfe, die nur ein Drache geben kann.]=],
		},
	},
})

Translate("deDE", "misty-reed-strand", {
	title = "Nebelschilfstrand",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Nebelschilfstrand ist die lange Ostküste des Sumpfes, wo die Marsch in Sand und die graue Brandung des verbotenen Meeres übergeht. {link:murlocs}Murlocs{/link} drängen sich an seinen Stränden: Plünderer, Fleischfresser, Tintenspeier und Orakel. Große Krabbler huschen zwischen den Felsen umher, und Sägezahnschnapper lauern in den Untiefen. An seinem Südende steht der Nebelschilfposten, ein kleines Lager der {link:horde}Horde{/link}. Seine {link:orcs}Orcs{/link} beobachten das Meer, und sie werden {link:stonard}Stonard{/link} alarmieren, falls die Murlocs je in großer Zahl kommen.]=],
		},
	},
})

Translate("deDE", "misty-valley", {
	title = "Das neblige Tal",
	aliases = { "Nebliges Tal" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Das neblige Tal ist das Westtor des Sumpfes, wo die toten Lande des {link:deadwind-pass}Gebirgspasses der Totenwinde{/link} in die Marsch abfallen. Zu jeder Stunde liegt dichter Nebel in seinen Senken. Die wandelnden Kräuter des Sumpfes sind hier am stärksten: alte Sumpfwandler, schwer von Moos, und ein großer, den die {link:orcs}Orcs{/link} den Morastfürsten nennen und der durch die fernen westlichen Tümpel wandert. Reisende aus dem Westen durchqueren zuerst {link:stranglethorn-vale}das Tal{/link}. Es ist die Warnung des Sumpfes an sie, was vor ihnen liegt.]=],
		},
	},
})

Translate("deDE", "sorrowmurk", {
	title = "Sorrowmurk",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Sorrowmurk ist die ferne östliche Marsch zwischen dem {link:pool-of-tears}Tränenteich{/link} und dem Meer. Es ist der düsterste Winkel eines düsteren Landes. Hier halten die ältesten Drachkin des grünen Schwarms ihre Wacht, und der Hauptmann der Drachkin, den man Wyrmak nennt, soll die Streifen rund um den Tempel befehligen. Schattenpanther schleichen durch das Schilf. Selbst die {link:orcs}Orcs{/link} von {link:stonard}Stonard{/link} gehen nur selten hier entlang, wenn sie nicht müssen.]=],
		},
	},
})

Translate("deDE", "stagalbog", {
	title = "Stagalbog",
	aliases = { "Stagalboghöhle" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Stagalbog ist eine weitläufige Fläche fauliger Tümpel im Südosten des Sumpfes. Verschlungene Schrecken aus Kraut und Wurzel waten durch seine Wasser, und die Schuppenbanne des grünen Drachenschwarms bestreifen seine Ufer. Nahe der Küste öffnet sich eine Höhle in den Hügeln. Sie ist ein Unterschlupf der {link:murlocs}Murlocs{/link}, und es heißt, dass ihr Anführer, den die {link:orcs}Orcs{/link} den {link:swamp-talker}Sumpfsprecher{/link} nennen, darin haust. Befehle der {link:horde}Horde{/link} verschwanden in dieser Höhle, zusammen mit den Murlocs, die sie an sich rissen.]=],
		},
	},
})

Translate("deDE", "splinterspear-junction", {
	title = "Splitterspeerkreuzung",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Splitterspeerkreuzung ist eine Wegkreuzung im Westen des Sumpfes. Hier trifft die Straße vom {link:deadwind-pass}Gebirgspass der Totenwinde{/link} auf den Weg, der nach Süden zu den {link:blasted-lands}Verwüsteten Landen{/link} und zur {link:nethergarde-keep}Burg Nethergarde{/link} führt. Jede Karawane der {link:alliance}Allianz{/link}, die zur Burg will, muss hier vorbei, und nicht alle kommen heil vorbei. Das Wrack einer solchen Karawane liegt nahe der Straße, wo ihr letzter {link:the-night-watch}Wächter{/link} noch immer über das wacht, was die Verirrten zurückließen.]=],
		},
	},
})

Translate("deDE", "the-shifting-mire", {
	title = "Der Wabersumpf",
	aliases = { "Wabersumpf" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Wabersumpf ist das Herz des nassen Landes im Sumpf, ein Irrgarten aus Tümpeln und nachgebendem Boden zwischen {link:stonard}Stonard{/link} und den westlichen Straßen. Seine Pfade ändern sich mit jedem Regen, und keine Karte von ihm bleibt lange richtig. Junge Krokilisken sonnen sich auf seinen Schlammbänken, und Kummerspinner spannen ihre Netze zwischen den ertrunkenen Bäumen. Die {link:orcs}Orcs{/link} von Stonard schicken Späher hinein, und nicht alle kommen zurück.]=],
		},
	},
})

Translate("deDE", "itharius", {
	title = "Itharius",
	subtitle = "Drache des grünen Schwarms",
	found = "Itharius' Höhle, im Südwesten des Sumpfes",
	hint = [=[Sucht den Drachen, der in einer Höhle im Südwesten des Sumpfes haust.]=],
	allegiance = "Grüner Drachenschwarm · Yseras Schwarm",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Itharius ist ein Drache des grünen Schwarms, des Schwarms von {red:ysera}Ysera{/red}, der den {link:emerald-dream}Smaragdgrünen Traum{/link} bewacht. Er hat seinen Hort in einer Höhle am Südwestrand des Sumpfes, fern vom {link:pool-of-tears}Tränenteich{/link}, wo der Rest seiner Art Wache hält. Welpen seines Schwarms schlafen in der Marsch vor seiner Tür. Er spricht wenig von sich selbst. Er ist geduldig und ernst, und er misst Sterbliche an den Entscheidungen, die sie treffen.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Die grünen Drachen kamen in den Sumpf, um die Priester {link:hakkar}Hakkar{/link}s daran zu hindern, ihren Gott in die Welt zurückzurufen. Die meisten von ihnen dulden keinen Sterblichen in ihrer Nähe. Itharius ist der Einzige ihrer Wacht, der mit Sterblichen als Verbündeter spricht und sie um Hilfe bittet.]=],
		},
		{
			title = "Taten",
			text = [=[• Er hat seinen Hort am Rand des Sumpfes, abseits der Drachen des Tränenteichs.
• Er spricht aus der Ferne durch einen Eidstein zu Sterblichen, einen Stein, der an den Auftrag seines Schwarms gebunden ist.
• Er wacht über die jungen Welpen seines Schwarms.
• Er schickt seine sterblichen Verbündeten auf der Suche nach Hilfe bis nach {link:winterspring}Winterquell{/link}.]=],
		},
		{
			title = "Nicht überliefert",
			text = [=[Kein Bericht erzählt, wie lange Itharius schon im Sumpf haust oder warum er seinen Hort so fern vom versunkenen Tempel hält. Sein Alter und sein Rang unter den grünen Drachen sind unbekannt.]=],
		},
	},
	chapters = {
		{
			title = "Der Eidstein",
			hint = [=[Bringt dem Drachen einen Edelstein, der die Essenz eines seiner Artgenossen birgt.]=],
			text = [=[Eranikus vom grünen Schwarm war beauftragt, die Atal'ai daran zu hindern, ihren Gott jemals wieder hervorzubringen. Dieser Auftrag ist gescheitert, und die Verderbnis des Tempels hat ihn ergriffen. Ein Teil seines Geistes, der noch ihm selbst gehört, wurde in einen Edelstein gebunden und aus den versunkenen Hallen getragen. Durch einen Eidstein bittet Itharius um diesen Stein. Er verspricht nicht, dass der Weg kurz sein wird. Er sagt nur, dass eine Seele, die es wert ist, gerettet zu werden, das Opfer wert ist.]=],
		},
		{
			title = "Eine Stimme für den Schläfer",
			hint = "Folgt dem Rat des Drachen in den hohen Norden.",
			text = [=[Eranikus liegt zwischen Schlaf und Tod, gefangen in einem Netz aus Albträumen. Seine Essenz ist schwer verdorben, doch Itharius glaubt, dass er noch erreicht werden kann. Er schickt seinen Verbündeten nach Norden in den Schnee des östlichen Winterquells, zu einem menschlichen Medium namens {link:umbranse-the-spiritspeaker}Umbranse{/link} der Geistersprecher, der für die Toten spricht. Eranikus ist nicht tot, doch Itharius hofft, dass eine solche Gabe ihn dennoch erreichen kann.]=],
		},
	},
	mentions = {
		{ text = "Die Essenz von Eranikus" },
		{ text = "In Eranikus' eigenen Worten" },
		{
			text = [=[Traumstaub im Sumpf, von den Welpen seines Schwarms gesammelt]=],
		},
	},
	bonds = {
		{ id = "eranikus", name = "Eranikus", note = "ein Drache seines Schwarms, den er erlösen will" },
		{ id = "umbranse-the-spiritspeaker", name = "Umbranse der Geistersprecher", note = "ein sterblicher Verbündeter in Winterquell" },
	},
})

Translate("deDE", "fel-zerul", {
	title = "Fel'zerul",
	subtitle = "Gesandter des Kriegshäuptlings",
	found = "Stonard, in der großen Halle",
	hint = [=[Sprecht mit dem Orc in Stonard, der den versunkenen Tempel erforscht.]=],
	allegiance = "Horde · Stonard",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Fel'zerul ist der {link:orcs}Orc{/link}, den der Kriegshäuptling {link:thrall}Thrall{/link} in {link:swamp-of-sorrows}die Sümpfe des Elends{/link} schickte, um zu erfahren, welche seltsamen Dinge im {link:temple-of-atal-hakkar}Tempel von Atal'Hakkar{/link} vor sich gingen. Er kam in der Erwartung eines Trolltempels voller dunkler Zauberwirker. Stattdessen fand er einen See, unter dem der Tempel versunken lag, und grüne Drachen, die am Ufer Wache standen. Seitdem arbeitet er von {link:stonard}Stonard{/link} aus daran, die Geschichte aus Überbleibseln der Atal'ai zusammenzusetzen.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Fel'zerul steht für eine {link:horde}Horde{/link}, die die Mächte ihrer Welt verstehen will. Er fürchtet die Atal'ai, doch er glaubt auch, dass ihre Zauber eines Tages der Horde dienen könnten. Durch seine geduldigen Studien erfährt die Horde von dem Propheten, der den Tempel führt, und von dem Ritual, das den {link:hakkar}Blutgott{/link} zurückbringen könnte.]=],
		},
		{
			title = "Taten",
			text = [=[• Er sammelt die Götzenbilder und Fetische der Atal'ai rund um den {link:pool-of-tears}Tränenteich{/link}.
• Seine Späher bringen ein Verbannungsurteil zurück, mit Blut auf getrocknete Haut geschrieben.
• Er schickt die Relikte des Tempels nach Norden zu einem verbannten Priester der Atal'ai im {link:the-hinterlands}Hinterland{/link}.
• Er schickt Streiter der {link:horde}Horde{/link} in den versunkenen Tempel selbst.]=],
		},
		{
			title = "Nicht überliefert",
			text = [=[Nichts ist über Fel'zeruls Leben geschrieben, bevor der Kriegshäuptling ihn in den Sumpf schickte.]=],
		},
	},
	chapters = {
		{
			title = "Relikte des Teichs",
			hint = [=[Sammelt, was die Atal'ai an den Ufern des Tränenteichs zurückließen.]=],
			text = [=[Niemand in {link:stonard}Stonard{/link} wusste, was die Atal'ai in ihrem Tempel getan hatten. Fel'zerul wusste nur, dass dort große Magie am Werk gewesen war und dass etwas schrecklich schiefgegangen war. Er begann mit den Relikten, die im Schlamm des Seeufers lagen. Eines nach dem anderen untersuchte er sie, um zu erfahren, was die {link:trolls}Trolle{/link} zu erreichen gehofft hatten.]=],
		},
		{
			title = "Die Warnung des Verbannten",
			hint = [=[Bringt die Relikte des Tempels zu dem, den die Atal'ai verstießen.]=],
			text = [=[Ein Späher brachte ihm ein Urteil, mit Blut auf getrocknetes Fleisch geschrieben. Es nannte einen Priester der Atal'ai, der zur Verbannung unter die {link:witherbark-trolls}Witherbarktrolle{/link} des Hinterlands verurteilt worden war. Fel'zerul schickte die Relikte zu diesem Verbannten. Die Antwort, die zurückkam, war ernst. Die Relikte seien harmlos, sagte der Verbannte. Doch der Hohepriester {link:jammal-an-the-prophet}Jammal'an{/link} habe eine Prophezeiung, und wenn er die richtige Verzauberung für seine Fetische gefunden habe, schwebe die ganze Welt in Gefahr.]=],
		},
		{
			title = "Die Fetische Hakkars",
			hint = [=[Betretet den versunkenen Tempel und nehmt die Fetische der Atal'ai an Euch.]=],
			text = [=[{link:jammal-an-the-prophet}Jammal'an der Prophet{/link} glaubt, dass der Gott den Atal'ai ewiges Leben schenken wird, wenn {link:hakkar}Hakkar{/link} zurückkehrt. Fel'zerul nennt es eine List, die das Verderben vor seiner Zeit bringen wird. Er fürchtet weniger die Prophezeiung als die Fetische, die sie erfüllen könnten. Er schickte Streiter der {link:horde}Horde{/link} hinab in den Tempel, um sie zu holen. Als sie mit den Fetischen in der Hand zurückkehrten, ernannte er sie zu Streitern der Horde.]=],
		},
	},
	mentions = {
		{ text = "{link:pool-of-tears}Tränenteich{/link}" },
		{ text = "Der Verbannte der Atal'ai" },
		{ text = "Zurück zu Fel'Zerul" },
		{
			text = [=[{link:temple-of-atal-hakkar}Der Tempel von Atal'Hakkar{/link}]=],
		},
	},
	bonds = {
		{ id = "atal-ai-exile", name = "Verbannter der Atal'ai", note = "der verstoßene Priester, der seine Relikte deutet" },
		{ id = "thrall", name = "Thrall", note = "der Kriegshäuptling, der ihn schickte" },
	},
})

Translate("deDE", "fallen-hero-of-the-horde", {
	title = "Gefallener Held der Horde",
	subtitle = "Geist des Sumpfes",
	found = [=[Der Südrand des Sumpfes, neben der Straße in die Verwüsteten Lande]=],
	hint = [=[Sucht den ruhelosen Geist, der neben der südlichen Straße wartet.]=],
	allegiance = "Horde (einst)",
	aliases = { "Gefallener Held" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Nahe der Straße, die nach Süden in die {link:blasted-lands}Verwüsteten Lande{/link} führt, steht der Geist eines Kriegers der {link:horde}Horde{/link}. Im Leben befehligte er ein Regiment namens Thralls Griff. Er führte es in die Verwüsteten Lande, ohne auf seine Befehle zu warten, und das Regiment wurde vernichtet. Nun steht er dort, wo er fiel, und wartet noch immer auf Befehle, die nie kamen. Selbst kann er keinen Schlag führen. Er kann die Lebenden nur um Hilfe bitten, und er bittet Krieger der {link:alliance}Allianz{/link} wie der Horde gleichermaßen.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Der Gefallene Held ist Zeuge eines Krieges, den der größte Teil der Welt vergessen hat. Jenseits der Ruinen des Dunklen Portals herrschen noch immer Dämonen über die Verwüsteten Lande, unter einem Fürsten namens {link:razelikh-the-defiler}Razelikh der Entweiher{/link}. Der Gefallene Held weiß das besser als jeder Lebende. Er lehrt, dass der wahre Feind nicht die {link:alliance}Allianz{/link} oder die {link:horde}Horde{/link} ist, sondern die Legion, die auf beide wartet.]=],
		},
		{
			title = "Taten",
			text = [=[• Er führte das Regiment Thralls Griff in die Verwüsteten Lande, bevor seine Befehle ihn erreichten.
• Er ruft die Lebenden auf, die Seelen seiner Männer zu befreien und die Macht des Dämonenfürsten zu brechen.
• Er heißt die {link:alliance}Allianz{/link} willkommen, an der Seite der {link:horde}Horde{/link} gegen die Dämonen zu kämpfen.
• Er prüft Krieger aller Völker und belohnt jene, die sich als würdig erweisen.]=],
		},
		{
			title = "Nicht überliefert",
			text = [=[Nichts ist über das Leben dieses Kriegers geschrieben, bevor Thralls Griff nach Süden geschickt wurde. Ob Trebor sein eigener Name war, machte Kiriths Geist nicht deutlich.]=],
		},
	},
	chapters = {
		{
			title = "Die verschollenen Befehle",
			hint = [=[Erfahrt, was aus den Befehlen wurde, die der gefallene Kommandant nie erhielt.]=],
			text = [=[Im Tod konnte er nur an die Befehle denken. {link:dispatch-commander-ruag}Botenkommandant Ruag{/link} von {link:stonard}Stonard{/link} schwor, sie geschickt zu haben. Seine Reiter wurden auf der Straße von {link:murlocs}Murlocs{/link} überfallen, und nur einer von ihnen überlebte. Dieser Überlebende, {link:bengor}Bengor{/link}, konnte kaum sprechen. Er sagte, ein Murloc namens {link:swamp-talker}Sumpfsprecher{/link} habe ihm die Befehle aus den Händen gerissen und sei nach Osten in eine Höhle geflohen. Der Gefallene Held erfuhr, dass seine Männer nicht hätten sterben müssen. Neunzehn von ihnen hätten verschont bleiben können, hätte er nur gewartet.]=],
		},
		{
			title = "Die Steine, die binden",
			hint = [=[Befreit die Seelen des gefallenen Regiments aus den Steinen der Verwüsteten Lande.]=],
			text = [=[Die Dämonen ließen die Soldaten von Thralls Griff nicht ruhen. Ihre Seelen wurden in Steine gebunden, die über die Verwüsteten Lande verstreut waren, achtzehn an der Zahl. Erst wenn die Steine zerbrochen waren, konnten die Männer Frieden finden. Als der letzte zersprang, wusste der Gefallene Held, dass seine lange Schuld abgetragen zu werden begann.]=],
		},
		{
			title = "Der verlorene Leutnant",
			hint = [=[Ergründet das Schicksal des einen Leutnants, der nie gefunden wurde.]=],
			text = [=[Einer seiner Offiziere wurde noch immer vermisst. {link:kirith-the-damned}Leutnant Kirith{/link} war an seiner Seite in den Höhlen eines Dämons namens {link:archmage-allistarj}Allistarj{/link} gefangen gehalten und gefoltert worden, doch Kiriths Wille war unter der Folter zerbrochen. Der Gefallene Held hörte seine Schreie aus seinem eigenen Käfig, und dann hörte er nichts mehr. Als Kiriths Geist endlich gefunden wurde, antwortete er mit einem Namen: Trebor.]=],
		},
		{
			title = "Der Entweiher",
			hint = [=[Vereint das zerbrochene Amulett und stellt Euch dem Dämonenfürsten der Verwüsteten Lande.]=],
			text = [=[{link:razelikh-the-defiler}Razelikh der Entweiher{/link} beherrschte die Verwüsteten Lande durch drei Diener. Jeder trug ein Drittel eines Amuletts, und solange sie es hielten, konnten sie in den Landen des Dämons nicht sterben. Der Gefallene Held schickte seine Streiter aus, um die drei zu zerschlagen und das Amulett wieder zu vereinen und dann zum Hort des Dämons auf dem höchsten Gipfel hinaufzusteigen. Als der Entweiher fiel, bat der Gefallene Held um sein Horn. Es sollte der Beweis sein, dass in einer vom Krieg zerbrochenen Welt noch Helden leben.]=],
		},
	},
	mentions = {
		{ text = "Tiefer Fall" },
		{ text = "Der Entehrte" },
		{
			text = [=[Kleinliche Zänkereien, die {link:alliance}Allianz{/link} kommt ihm zu Hilfe]=],
		},
		{ text = "Eine Geschichte des Kummers" },
		{ text = "Helden von einst, mit dem Geist von Korporal Thund Splithoof" },
		{ text = "Der Schutz der Dunkelheit" },
		{ text = "Der Dämonenjäger" },
		{ text = "Zurück in die Verwüsteten Lande" },
		{ text = "Das zerbrochene Amulett vereinen" },
		{ text = "Ein ruheloser Geist" },
		{ text = "Kriegerverwandtschaft" },
		{ text = "Krieg gegen die Schattenschwörer" },
		{ text = "Voodoofedern" },
	},
	bonds = {
		{ id = "dispatch-commander-ruag", name = "Botenkommandant Ruag", note = "schickte die Befehle, die nie ankamen" },
		{ id = "bengor", name = "Bengor", note = "der letzte Reiter, der sie trug" },
		{ id = "swamp-talker", name = "Sumpfsprecher", note = "nahm die Befehle an sich" },
		{ id = "corporal-thund-splithoof", name = "Korporal Thund Splithoof", note = "einer seiner Männer" },
		{ id = "razelikh-the-defiler", name = "Razelikh der Entweiher", note = "Feind" },
	},
})

Translate("deDE", "dispatch-commander-ruag", {
	title = "Botenkommandant Ruag",
	subtitle = "Botenkommandant von Stonard",
	found = "Stonard, in der großen Halle",
	hint = "Sprecht mit dem Orc, der die Befehle Stonards verschickt.",
	allegiance = "Horde · Stonard",
	aliases = { "Ruag" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Botenkommandant Ruag schickt die Befehle Stonards an die Soldaten der {link:horde}Horde{/link} im Feld. Er erinnert sich noch an das Regiment namens Thralls Griff und an den Tag, an dem die Horde mit ihm einige ihrer besten Krieger verlor. Er fühlt sich schnell gekränkt, wenn auch nur angedeutet wird, er habe sie im Stich gelassen. Er habe ihre Befehle weitergegeben, sagt er, und seine Reiter hätten dafür mit Blut bezahlt.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Ruag hält das andere Ende der Geschichte des Gefallenen Helden. Die Befehle, die er schickte, kamen nie an, und der Verlust von Thralls Griff lastet noch immer auf {link:stonard}Stonard{/link}.]=],
		},
		{
			title = "Taten",
			text = [=[• Er schickte Reiter mit Befehlen für Thralls Griff und sah sie auf der Straße überfallen.
• Wer nach den Befehlen fragt, den schickt er zu {link:bengor}Bengor{/link}, dem letzten Überlebenden.]=],
		},
	},
	mentions = {
		{ text = "Der Entehrte" },
		{ text = "Die verschollenen Befehle" },
	},
	bonds = {
		{ id = "fallen-hero-of-the-horde", name = "Gefallener Held der Horde", note = "der Kommandant, der seine Befehle nie erhielt" },
		{ id = "bengor", name = "Bengor", note = "sein überlebender Reiter" },
	},
})

Translate("deDE", "bengor", {
	title = "Bengor",
	subtitle = "Überlebender des Hinterhalts",
	found = "Stonard, nahe dem Gasthaus",
	hint = [=[Sucht den gebrochenen Soldaten von Stonard, der die verlorenen Befehle trug.]=],
	allegiance = "Horde · Stonard",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Bengor war einer der Reiter, die die Befehle Stonards zum Regiment Thralls Griff trugen. Auf der Straße in die {link:blasted-lands}Verwüsteten Lande{/link} fielen {link:murlocs}Murlocs{/link} in großer Zahl über die Reiter her. Bengor allein überlebte, mit einer Speerwunde am Schädel. Er kann kaum sprechen, er kann nicht gehen, und er muss von anderen gefüttert werden. Doch er erinnert sich noch an den Namen des Murlocs, der ihm die Befehle aus den Händen nahm.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Bengors gebrochene Worte sind das einzige Zeugnis des Hinterhalts. Durch sie erfährt der Gefallene Held die Wahrheit über seinen eigenen Tod.]=],
		},
		{
			title = "Taten",
			text = [=[• Er trug die Befehle für Thralls Griff, bis die {link:murlocs}Murlocs{/link} zuschlugen.
• Er nennt den {link:swamp-talker}Sumpfsprecher{/link} und weist nach Osten zu dessen Höhle.]=],
		},
	},
	mentions = {
		{ text = "Die verschollenen Befehle" },
		{ text = "Der {link:swamp-talker}Sumpfsprecher{/link}" },
	},
	bonds = {
		{ id = "dispatch-commander-ruag", name = "Botenkommandant Ruag", note = "sein Kommandant" },
		{ id = "swamp-talker", name = "Sumpfsprecher", note = "der Murloc, der ihn niederstreckte" },
	},
})

Translate("deDE", "helgrum-the-swift", {
	title = "Helgrum der Schnelle",
	subtitle = "Läufermeister von Stonard",
	found = "Stonard",
	hint = [=[Sprecht mit dem schnellen Orc, der die Läufer von Stonard führt.]=],
	allegiance = "Horde · Stonard",
	aliases = { "Helgrum" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Helgrum der Schnelle hält die Nachrichtenwege zwischen {link:stonard}Stonard{/link} und den anderen Außenposten der {link:horde}Horde{/link} aufrecht. Der schwerste davon führt nach Norden nach {link:kargath}Kargath{/link} im {link:badlands}Ödland{/link}, einem harten Land nahe dem {link:loch-modan}Loch Modan{/link} der {link:alliance}Allianz{/link}. Läufer auf dieser Straße gehen oft verloren, und Helgrum braucht Läufer, die die Reise schaffen und überleben.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Helgrum verbindet {link:stonard}Stonard{/link} mit dem Rest der {link:horde}Horde{/link} im Osten. Aus den Berichten, die er sammelt, hat er erkannt, dass die {link:alliance}Allianz{/link} eigene Sorgen hat und dass manche Feinde womöglich gemeinsame sind.]=],
		},
		{
			title = "Taten",
			text = [=[• Er schickt Läufer zu {link:neeka-bloodscar}Neeka Bloodscar{/link}, der obersten Späherin von {link:kargath}Kargath{/link}.
• Er liest die Berichte aus dem Norden und wägt sie für {link:stonard}Stonard{/link} ab.]=],
		},
	},
	mentions = {
		{ text = "{link:neeka-bloodscar}Neeka Bloodscar{/link}" },
		{ text = "Meldet Euch bei Helgrum" },
	},
	bonds = {
		{ id = "neeka-bloodscar", name = "Neeka Bloodscar", note = "oberste Späherin von Kargath" },
	},
})

Translate("deDE", "dar", {
	title = "Dar",
	subtitle = "Händler von Stonard",
	found = "Stonard, nahe dem Gasthaus",
	hint = [=[Sucht den Händler von Stonard, der Fleisch nach Orgrimmar verschifft.]=],
	allegiance = "Horde · Stonard",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Dar ist ein Händler aus {link:stonard}Stonard{/link}. Er sammelt Vorräte für das Lager der {link:horde}Horde{/link} am {link:eastern-strand}Oststrand{/link}, und er verschifft das Fleisch der Küste zurück zu seinen Kunden in {link:orgrimmar}Orgrimmar{/link}, die die Beine der großen Krabbler über alles schätzen. Er kostet die Ware immer zuerst, und er hält ein Fass Wein für jene bereit, die ihm bringen, was er will. Die {link:orcs}Orcs{/link} vom Strand sagen, seine Manieren seien besser als sein Geruch, wenn auch nicht viel.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Dar ist ein kleiner, aber lebendiger Faden zwischen der {link:capital-city}Hauptstadt{/link} der {link:horde}Horde{/link} und ihrer Festung im Sumpf.]=],
		},
		{
			title = "Taten",
			text = [=[• Er schickt Fleisch und Vorräte nach Osten zum Nebelschilfposten.
• Er verschifft Krabblerfleisch nach {link:orgrimmar}Orgrimmar{/link}.]=],
		},
	},
	mentions = {
		{ text = "Kein Überschuss" },
		{ text = "Frisches Fleisch" },
	},
	bonds = {
		{ id = "tok-kar", name = "Tok'Kar", note = "erhält seine Vorräte" },
	},
})

Translate("deDE", "tok-kar", {
	title = "Tok'Kar",
	subtitle = "Schmied des Nebelschilfpostens",
	found = "Nebelschilfposten, am Oststrand",
	hint = [=[Sucht den Orc, der im Lager der Horde am Oststrand Waffen schmiedet.]=],
	allegiance = "Horde · Stonard",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Tok'Kar dient am Nebelschilfposten, der Wacht der {link:horde}Horde{/link} an der Ostküste. Zwischen seinen Wachschichten kocht er für seine Kameraden und schmiedet ihre Waffen, und in beidem ist er schnell und geschickt geworden. Er verarbeitet die Scheren der Sägezahnschnapper zu Klingen. Er bereut seinen Posten nicht. Er hätte nur gern eines Tages einen richtigen Turm, um ihn zu halten.]=],
