		},
		{
			title = "Taten",
			text = [=[• Er bewacht den Zugang nach {link:stonard}Stonard{/link} vom Meer her.
• Er schmiedet Waffen aus den Scheren der Schnapper der Küste.]=],
		},
	},
	mentions = {
		{ text = "Kein Überschuss" },
		{ text = "Kein Überschuss" },
		{ text = "Bedrohung aus dem Meer" },
		{ text = "Bedrohung aus dem Meer" },
	},
	bonds = {
		{ id = "katar", name = "Katar", note = "sein Kamerad am Strand" },
		{ id = "dar", name = "Dar", note = "schickt ihm Vorräte" },
	},
})

Translate("deDE", "katar", {
	title = "Katar",
	subtitle = "Wächter des Meeres",
	found = "Nebelschilfposten, am Oststrand",
	hint = "Sprecht mit dem Orc im Strandlager, der das Meer hasst.",
	allegiance = "Horde · Stonard",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Katar hält am Strand des Nebelschilfpostens Wache. Er hasst das Meer, und er hasst jedes Geschöpf, das daraus hervorkommt, die {link:murlocs}Murlocs{/link} am meisten. Er nennt sich so geduldig wie ein alter Stein von {red:draenor}Draenor{/red}. Er schwört, dass die Fischmenschen die Grenzen der {link:horde}Horde{/link} nicht überschreiten werden, solange er noch steht, und er lächelt nur, wenn er sie sterben hört.]=],
