	},
	mentions = {
		{ text = "Bedrohung aus dem Meer" },
		{ text = "Bedrohung aus dem Meer" },
		{ text = "Bedrohung aus dem Meer" },
		{ text = "Anhaltende Bedrohung" },
	},
	bonds = {
		{ id = "tok-kar", name = "Tok'Kar", note = "sein Kamerad am Strand" },
	},
})

Translate("deDE", "infiltrator-marksen", {
	title = "Infiltrator Marksen",
	subtitle = "Gefangener von Stonard",
	found = "Stonard, unter Bewachung",
	hint = [=[Sucht den menschlichen Gefangenen, der in Stonard festgehalten wird.]=],
	allegiance = "Allianz",
	aliases = { "Marksen" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Marksen ist ein menschlicher Spion der {link:alliance}Allianz{/link}, gefasst nahe dem Lager der Verlassenen im {link:beggar-s-haunt}Bettlerschlupfwinkel{/link} und in {link:stonard}Stonard{/link} gefangen gehalten. Seit Tagen hat man ihm nichts zu trinken gegeben. Er fleht um Gnade und behauptet, Geheimnisse zu kennen, die über die Allianz selbst hinausreichen: Verrat in hohen Kreisen, der, wie er sagt, ans Licht gebracht werden muss. Die {link:forsaken}Verlassenen{/link} wollen diese Geheimnisse, und sie haben nicht vor, höflich zu fragen.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Marksens Geheimnis verbindet {link:stonard}Stonard{/link} mit den verborgenen Streitigkeiten der Königreiche. Was er weiß und wer es sonst noch weiß, ist nicht überliefert.]=],
		},
	},
	chapters = {
		{
			title = "Nichts als die Wahrheit",
			hint = [=[Bringt dem Gefangenen von Stonard ein Getränk von den Verlassenen.]=],
			text = [=[Der Apotheker Faustin von den Verlassenen braute ein Serum, das einem Mann die Zunge löst, und der Todespirscher Zraedus mischte es in einen Becher Ale. Ein Becher Ale war das Einzige, was der durstige Gefangene nicht ablehnen würde. Marksen trank ihn gern aus und begann zu sprechen.]=],
		},
	},
	mentions = {
		{ text = "Nichts als die Wahrheit" },
	},
	bonds = {
