})

Translate("deDE", "magtoor", {
	title = "Magtoor",
	subtitle = "Stimme des sicheren Hafens",
	found = "Der sichere Hafen",
	hint = [=[Sprecht mit dem Draenei, der die Verbannten des sicheren Hafens anführt.]=],
	allegiance = "Draenei des sicheren Hafens",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Magtoor spricht für die verbannten Draenei des sicheren Hafens. Sein Volk legte einen langen Weg zurück, um {link:azeroth}Azeroth{/link} zu erreichen, und nicht alle überstanden ihn unversehrt. Jene, die ihren Verstand verloren, wurden zu den Verirrten. Sie nahmen das {link:fallow-sanctuary}Fallow Heiligtum{/link} ein, und sie stahlen die heiligen Draenethystkristalle des sicheren Hafens. Magtoor fürchtet, dass ohne diese Kristalle auch sein eigenes Volk den Weg verlieren könnte.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Durch Magtoor erfährt die Welt, was die Verirrten wirklich sind: keine im Sumpf geborenen Ungeheuer, sondern ein von seiner Reise gebrochenes Volk.]=],
		},
		{
			title = "Taten",
			text = [=[• Er sucht die Rückgabe des Draenethysts, das die Verirrten gestohlen haben.
• Er frohlockt über den Tod von {link:noboru-the-cudgel}Noboru{/link}, der sein Volk terrorisierte.]=],
		},
	},
	chapters = {
		{
			title = "Die gestohlenen Kristalle",
			hint = [=[Holt die Draenethystkristalle zurück, die aus dem sicheren Hafen gestohlen wurden.]=],
			text = [=[Den Verbannten fehlte die Kraft, in das {link:fallow-sanctuary}Fallow Heiligtum{/link} zu gehen und sich zurückzuholen, was ihnen gehörte. Magtoor konnte nur Fremde bitten, für sie zu gehen. Als die Kristalle zurückkamen, dankte er und sagte, der sichere Hafen stehe in ihrer Schuld.]=],
		},
	},
	mentions = {
		{ text = "Draenethystkristalle" },
		{ text = "{link:noboru-the-cudgel}Noboru der Knüppel{/link}" },
	},
	bonds = {
		{ id = "noboru-the-cudgel", name = "Noboru der Knüppel", note = "Feind seines Volkes" },
		{ id = "ongeku", name = "Ongeku", note = "ein Verirrter, der Draenethyst hütet" },
	},
})

Translate("deDE", "watcher-biggs", {
	title = "Wächter Biggs",
	subtitle = "Wache der verlorenen Karawane",
	found = "Das Wrack seiner Karawane, an der westlichen Straße",
	hint = [=[Sucht den Wächter, der die Überreste einer Karawane an der westlichen Straße bewacht.]=],
	allegiance = "Allianz",
	aliases = { "Biggs" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Wächter Biggs war Wache einer Karawane der {link:alliance}Allianz{/link} auf dem Weg von {link:darkshire}Dunkelhain{/link} zur {link:nethergarde-keep}Burg Nethergarde{/link}. Die Verirrten fielen im Sumpf über sie her. Sie töteten die anderen Wachen, verstreuten die Vorräte und schleppten einen Wagen in ihr Dorf. Biggs allein überlebte. Er hat geschworen, zu bewachen, was übrig ist, und er will damit die Burg erreichen.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Biggs zeigt den Preis der Straße der {link:alliance}Allianz{/link} durch den Sumpf. Die Zauberer von {link:nethergarde-keep}Nethergarde{/link}, die über das {link:dark-portal}Dunkle Portal{/link} wachen, sind auf Vorräte angewiesen, die hier vorbei müssen.]=],
		},
		{
			title = "Taten",
			text = [=[• Er verteidigt sein zerstörtes Lager gegen die Tiere des Sumpfes.
• Er sucht die Truhe mit Reagenzien, die ins {link:fallow-sanctuary}Fallow Heiligtum{/link} gebracht wurde.
• Er repariert seinen Wagen mit Treibholz von der Küste.
• Er schickt seine wichtigsten Vorräte weiter nach {link:nethergarde-keep}Nethergarde{/link}.]=],
		},
	},
	chapters = {
		{
			title = "Die verlorene Karawane",
			hint = [=[Holt die Truhe zurück, die die Verirrten von der Karawane fortschleppten.]=],
			text = [=[Bevor er die Besinnung verlor, sah Biggs, wie einer der Wagen nach Norden zum Dorf der Verirrten gezogen wurde. Er trug eine Truhe mit Reagenzien für die Zauberer von {link:nethergarde-keep}Burg Nethergarde{/link}. Er weiß nicht, was die Zauberer damit tun. Er weiß nur, dass ihre Arbeit mit dem Dunklen Portal und mit der Sicherheit der {link:alliance}Allianz{/link} verbunden ist.]=],
		},
	},
	mentions = {
		{ text = "Vordringende Tierwelt" },
		{ text = "Die verlorene Karawane" },
		{ text = "Treibholz" },
		{ text = "Liefert die Ladung aus" },
	},
	bonds = {
		{ id = "galen-goodward", name = "Galen Goodward", note = "ein weiterer Gefangener der Verirrten" },
	},
})

Translate("deDE", "galen-goodward", {
	title = "Galen Goodward",
	subtitle = "Gefangener der Verirrten",
	found = "Ein Käfig im Fallow Heiligtum",
	hint = [=[Befreit den Menschen, der im Dorf der Verirrten gefangen gehalten wird.]=],
	allegiance = "Keine",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Galen Goodward ist ein Mensch, den die Verirrten im {link:fallow-sanctuary}Fallow Heiligtum{/link} gefangen halten. Er ist sicher, dass sie ihn essen wollen. Er hat ein Lager im Sumpf nördlich von {link:stonard}Stonard{/link}, und darin eine Geldkassette, die kein Schlüssel öffnen kann. Er verspricht ihren Schatz jedem, der ihm zur Flucht verhilft.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Galens Schicksal zeigt, wie die Verirrten mit jenen umgehen, die sich in die Nähe ihres Dorfes verirren.]=],
		},
	},
	chapters = {
		{
			title = "Galens Flucht",
			hint = "Führt den Gefangenen aus dem Dorf der Verirrten.",
			text = [=[Das Schlüsselloch von Galens Geldkassette ist mit schwarzem Harz gefüllt, und kein Schlüssel könnte sich je darin drehen. Doch {link:prince-galen-trollbane}Galen{/link} kannte ihr Geheimnis: einen verborgenen Riegel unter der Kassette. Als er frei war, teilte er dieses Geheimnis, und die Kassette öffnete sich.]=],
		},
	},
	mentions = {
		{ text = "Galens Flucht" },
	},
	bonds = {
		{ id = "watcher-biggs", name = "Wächter Biggs", note = "ein weiteres Opfer der Verirrten" },
	},
})

