	allegiance = "Verirrte",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Ongeku ist ein Verirrter des Fallow Heiligtums, der einen Splitter Draenethyst besitzt, den roten Kristall, der den Draenei heilig ist. Der Kristall ist neu in dieser Welt. Er soll aus einem Land stammen, in dem Berge fliegen und Dämonen herrschen. Die Kunde von Ongekus Splitter ist weit gereist: Die Erde flüsterte davon {link:uthek-the-wise}Uthek{/link} zu, einem Zentaurenschamanen aus {link:desolace}Desolace{/link}, der seine Macht für den Gelkisklan wollte.]=],
		},
