	},
	mentions = {
		{ text = "Ongeku" },
	},
	bonds = {
		{ id = "uthek-the-wise", name = "Uthek der Weise", note = "suchte seinen Splitter" },
		{ id = "magtoor", name = "Magtoor", note = "dessen Volk seine Kristalle verlor" },
	},
})

